steps.input:
H,W=30,8
pts={(1,6),(3,7),(5,0),(5,7),(9,2),(12,2),(12,4),(17,6),(20,7),(21,5)}
# Confirm 10 markers (count input rows)
out=[[8]*W for _ in range(H)]
for r,c in pts: out[r][c]=7
for r in range(H):
    cs=sorted(c for rr,c in pts if rr==r)
    if len(cs)>1:
        for c in range(cs[0]+1,cs[-1]):
            if out[r][c]==8: out[r][c]=3
for c in range(W):
    rs=sorted(r for r,cc in pts if cc==c)
    if len(rs)>1:
        for r in range(rs[0]+1,rs[-1]):
            if out[r][c]==8: out[r][c]=3
out
